import{_ as o,o as i,c as a,ag as r}from"./chunks/framework.IxO3mcwW.js";const s="/getbiji-docs/images/classroom-01.png",l="/getbiji-docs/images/classroom-02.png",e="/getbiji-docs/images/classroom-03.png",d="/getbiji-docs/images/classroom-04.png",n="/getbiji-docs/images/classroom-05.png",p="/getbiji-docs/images/classroom-06.png",c="/getbiji-docs/images/classroom-07.png",q=JSON.parse('{"title":"课堂录音","description":"","frontmatter":{},"headers":[],"relativePath":"voice/classroom.md","filePath":"voice/classroom.md","lastUpdated":1773215704000}'),g={name:"voice/classroom.md"};function h(m,t,u,_,b,x){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="课堂录音" tabindex="-1">课堂录音 <a class="header-anchor" href="#课堂录音" aria-label="Permalink to &quot;课堂录音&quot;">​</a></h1><blockquote><p>上课录音，下课秒出学霸笔记，高效复习不费力</p></blockquote><p>专为学生打造的课堂录音功能，自动转写讲课内容，智能识别老师强调的考点重点，生成结构清晰的学霸级笔记。拍PPT、记要点、传资料，让复习变得轻松高效。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>大学课程</strong>：专业课、公共课实时记录，重点考点自动加粗标注</li><li><strong>讲座分享</strong>：学术讲座、技术分享会完整保存，方便后续回顾</li><li><strong>培训课程</strong>：职业资格培训、技能培训课程内容整理</li><li><strong>复习备考</strong>：结合课程资料和录音笔记，AI辅导深度理解</li><li><strong>留学生课堂</strong>：英文等不同语种授课实时转写，语言不再是学习障碍</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>实时转写</strong>：老师讲课内容同步转为文字，不错过任何细节</li><li><strong>拍摄板书</strong>：随时拍下PPT、板书照片，自动整合进笔记</li><li><strong>随手记录</strong>：录音过程中可以随时记录重点和想法</li><li><strong>上传资料</strong>：支持上传课程PDF等资料，方便后续复习对照</li><li><strong>重点突出</strong>：自动识别老师强调的考点进行加粗展示（&quot;这个必考&quot;&quot;期末会考&quot;等）</li><li><strong>公式转写</strong>：数学公式自动转为LaTeX格式，清晰易读</li><li><strong>AI助手辅导</strong>：推出「学习辅导」模式，通过引导式提问帮你真正理解知识点</li></ul><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><ol><li><p>打开 App，点击首页底部「录音」按钮，选择「课堂录音」</p></li><li><p>同意 Get 笔记使用手机录音权限，然后点击红色按钮&quot;开始录音&quot;</p></li><li><p>开始录制后，录制页面会有实时转录的文字展示出来</p></li><li><p>点击底部「📷 拍重点」按钮，可以拍摄老师的PPT或板书</p></li><li><p>点击「✏️ 随手记」按钮，快速记下关键要点或问题</p></li><li><p>点击「📄 传资料」按钮，上传老师发的课件PDF/Word/PPT等文件（文件最多3个）</p></li><li><p>最终录制结束后，AI会自动对录音内容进行智能总结，生成课堂笔记，笔记会自动识别并标注老师强调的重点和考点</p></li></ol><h2 id="录制时长" tabindex="-1">录制时长 <a class="header-anchor" href="#录制时长" aria-label="Permalink to &quot;录制时长&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>单次时长</th><th>次数限制</th></tr></thead><tbody><tr><td>普通用户</td><td>1 小时</td><td>不限</td></tr><tr><td>会员用户</td><td>3 小时</td><td>不限</td></tr></tbody></table><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+s+'" alt="课堂录音入口" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="录音界面" style="width:180px;border-radius:8px;"><img src="'+e+'" alt="拍重点" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="随手记" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="传资料" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="课堂笔记" style="width:180px;border-radius:8px;"><img src="'+c+'" alt="重点标注" style="width:180px;border-radius:8px;"></div>',13)])])}const f=o(g,[["render",h]]);export{q as __pageData,f as default};
